typedef float rational_t;
typedef unsigned int uint32;
typedef unsigned long uint64;

void *operator new(unsigned int, unsigned int, const char *, int);

class pstring {
    uint64 pchunk[4];
    void pack_string(const char *);
public:
    pstring() { for (unsigned i=0; i<4; ++i) pchunk[i]=0; }
    pstring(const char *s) { pack_string(s); }
    pstring(const pstring& p) { for (unsigned i=0;i<4;++i) pchunk[i]=p.pchunk[i]; }
    pstring& operator=(const pstring& p) { if (&p!=this) for(unsigned i=0;i<4;++i)pchunk[i]=p.pchunk[i]; return *this; }
    pstring& operator=(const char *s) { pack_string(s); return *this; }
    bool is_set() const { return pchunk[0] != 0; }
};

class stringx; class vector3d; class entity;
class generic_interface {
public:
    virtual ~generic_interface();
    virtual bool get_ifc_num(const pstring&, float&);
    virtual bool set_ifc_num(const pstring&, float);
    virtual bool get_ifc_vec(const pstring&, vector3d&);
    virtual bool set_ifc_vec(const pstring&, const vector3d&);
    virtual bool get_ifc_str(const pstring&, stringx&);
    virtual bool set_ifc_str(const pstring&, const stringx&);
};
class entity_interface : public generic_interface {
protected: entity *my_entity;
public: explicit entity_interface(entity *e):my_entity(e){} virtual ~entity_interface();
};

template<class type> class basic_attribute {
    static pstring type_name;
    type value;
public:
    basic_attribute(const char *n,const type& v) { type a,b; _construct(n,v,a,b); }
    void _construct(const char *n,const type& v,const type&,const type&) { if(type_name.is_set()==false) type_name=n; value=v; }
    virtual ~basic_attribute() {}
    virtual const pstring& get_class_name() const { return type_name; }
};

#define ATTR(t,n,d) class n##_attrib: public basic_attribute<t> { static pstring attribute_name; public: n##_attrib():basic_attribute<t>(#t,d){} const pstring& get_name()const{return attribute_name;} };
